/* Additive integration. Training narratives, builders, genetics and potential are retained. */
const CARE_VERSION=1;
let careMigrationBlocked=false;
let csLastHealthDay=null;
function csDay(){return Math.floor((typeof careSimulationHour==='number'?careSimulationHour:pastureCalendarHour())/24);}
function csId(prefix){app.careSequence=(app.careSequence||0)+1;return `${prefix}:${app.careSequence}`;}
function csEscape(value){return mgEscape(String(value??''));}
function csOptions(values,current){return values.map(v=>`<option value="${csEscape(v)}" ${v===current?'selected':''}>${csEscape(v)}</option>`).join('');}
function csHorses(){return [...new Map([...(app.saleBarn||[]),...(app.npcSales||[]),...(app.sales2?.listings||[]).filter(l=>!['Complete','Cancelled','Sold Elsewhere'].includes(l.status)).map(l=>l.horse),...app.horses].filter(Boolean).map(h=>[h.id,h])).values()];}
function csEnsure(h,day=csDay()){HorseHealth.ensure(h,day);return h;}
function csSync(h){
  csEnsure(h);
  // Only severe restrictions project into old global blockers. Hidden diagnosis names never do.
  h.illnesses=h.medicalConditions.filter(c=>c.confirmed||!c.resolved&&HorseHealth.definition(c).restriction==='all').map(c=>({medicalId:c.id,name:c.confirmed?HorseHealth.definition(c).name:'Health concern requiring veterinary assessment',active:!c.resolved&&HorseHealth.definition(c).restriction==='all',hidden:!c.confirmed,severity:c.severity,remaining:0,impact:c.resolved?0:c.severity==='major'?8:3}));
  h.due ||= {};h.due.farrier=csDay()>h.hoofHealth.nextDue;h.hoofCare=h.hoofHealth.condition;
}
function csMigrate(data){
  if(!data.careVersion){
    // Preserve the actual serialized source and every named save before any hydration/migration.
    const serialized=JSON.stringify(data),key=`horse_game_pre_care_v1_${HorseHealth.hash(serialized)}`;
    if(!localStorage.getItem(key)){
      try{localStorage.setItem(key,JSON.stringify({source:serialized,legacySave:localStorage.getItem(SAVE_KEY),slots:localStorage.getItem(SAVE_SLOTS_KEY),createdAt:new Date().toISOString()}));}
      catch(error){careMigrationBlocked=true;app.careFeedback='Your original save is preserved. Loading and saving are blocked because its backup could not be stored. Free browser storage and reload.';throw new Error('The original save could not be backed up. Free browser storage before loading this save.');}
    }
  }
}
const CS_HYDRATE=hydrateFromSave;
hydrateFromSave=function(data){csLastHealthDay=null;csMigrate(data);const result=CS_HYDRATE(data);app.money=Number.isFinite(data.money)?data.money:app.money;app.careEconomy=data.careEconomy||{receipts:[],inventory:[],operations:{}};app.sales2=data.sales2||{version:1,sequence:0,listings:[],transactions:[],history:[]};app.careSequence=data.careSequence||0;app.riderExperience=data.riderExperience||0;app.careSelectedTransaction=data.careSelectedTransaction||null;app.healthPolicy=data.healthPolicy||'Local leisure';app.careVersion=CARE_VERSION;for(const l of app.sales2.listings)if(l.direction==='sell'){const owned=app.horses.find(h=>h.id===l.horseId);if(owned)l.horse=owned;}csHorses().forEach(h=>{csEnsure(h);csSync(h);});csImportListings();careMigrationBlocked=false;return result;};
const CS_SAVE=saveGame;
saveGame=function(...args){if(careMigrationBlocked)return false;app.careVersion=CARE_VERSION;return CS_SAVE(...args);};
const CS_BASE_HORSE=baseHorse;
baseHorse=function(...args){const h=CS_BASE_HORSE(...args);csEnsure(h);if(args[1]==='npc')h.careNewNPC=true;return h;};
function csImportListings(){
  const owned=new Map(app.horses.map(h=>[h.id,h]));
  for(const h of [...(app.saleBarn||[]),...(app.npcSales||[])]){
    const isOwned=owned.has(h.id),source=isOwned?owned.get(h.id):h;
    if(!Number.isFinite(h.price)||h.price<=0)continue;
    HorseSales.list(app,source,Math.round(h.price),csDay(),isOwned?'sell':'buy');
  }
}
// Old random monthly illness and timer cures are retired. Time processing owns new incidents.
maybeAddRandomIllness=function(){};
const CS_ADD_ILLNESS=addIllness;
addIllness=function(h,template){if(!h)return null;csEnsure(h);const names={'Pasture Fight Injury':'contusion','Pasture Bite Bruising':'contusion','Tendon Strain':'strain','Overtraining Strain':'strain','Muscle Soreness':'soreness','Back Soreness':'back','Saddle Rubbing':'rub','Suspensory Strain':'suspensory','Complete Tendon Rupture':'tendon-rupture','Stable Fracture':'stable-fracture','Unstable Fracture':'unstable-fracture'};const id=names[template.name]||Object.values(HorseHealth.catalog).find(d=>d.name===template.name)?.id||'legacy';const existing=HorseHealth.current(h).find(c=>c.diagnosis===id);if(existing)return {name:'a previously recorded physical concern',remaining:0,severity:existing.severity,active:true};
  const eventKey=`physical:${csDay()}:${template.name}`,outcomes=h.careIncidentOutcomes ||= {};const severity=outcomes[eventKey] ||= HorseHealth.injuryOutcome(h.healthSeed,eventKey);if(severity==='none')return null;
  const resolvedId=['tendon-rupture','unstable-fracture'].includes(id)&&severity!=='major'?'strain':['Pasture Fight Injury','Pasture Bite Bruising'].includes(template.name)?severity==='major'?'orthopedic':severity==='moderate'?'strain':'contusion':id;
  HorseHealth.add(h,resolvedId,csDay(),{legacyName:template.name,cause:'Recorded physical incident',severity});csSync(h);return {name:'a physical concern requiring assessment',remaining:0,severity:template.severity||'Easy',active:true};};
visibleIllnesses=function(h){csEnsure(h);return h.medicalConditions.filter(c=>c.confirmed).map(c=>({name:HorseHealth.definition(c).name,active:!c.resolved,remaining:0}));};
const CS_SIMULATE_HOUR=simulatePastureHour;
simulatePastureHour=function(hour){
  // The existing UI refreshes mood at the end of each skip. Keep that display
  // refresh from changing the RNG path of subsequent chronological simulation.
  for(const h of app.horses){const skip=h.training2?.lastSkipMood,previous=h.careSimulationMood;if(previous&&skip&&skip.hour>previous.hour&&h.mood===skip.to)h.mood=previous.value;}
  const day=Math.floor((hour+1)/24);if(csLastHealthDay!==day){for(const h of csHorses()){csEnsure(h,day);HorseHealth.advance(h,day,csContext(h),app);csSync(h);}HorseSales.advanceMarket(app,day);refreshRescueHorses();csLastHealthDay=day;}
  const result=CS_SIMULATE_HOUR(hour);for(const h of app.horses)h.careSimulationMood={hour,value:h.mood};return result;
};
function csContext(h){return {wetExposure:h.wetExposure===true,dustExposure:h.dustExposure===true,skinDamageExposure:h.skinDamageExposure===true,firmFooting:h.firmFooting===true,demandingWork:(h.fatigue||0)>60,poorTackFit:h.saddleFitGrade==='Poor',heatExposure:h.heatExposure===true,hydrationRisk:h.hydrationRisk===true,overexertion:(h.fatigue||0)>85,weightLoss:h.weightStatus==='Very Underweight',infectiousExposure:h.infectiousExposure===true,influenzaExposure:h.influenzaExposure===true,ehvExposure:h.ehvExposure===true,stranglesExposure:h.stranglesExposure===true,parasiteExposure:h.parasiteExposure===true,dentalOverdue:h.dentalOverdue===true,tackCorrected:h.tackConcernCorrected===true,airQualityCorrected:h.airQualityCorrected===true};}
const CS_MONTH=monthlyProgress;
monthlyProgress=function(...args){const result=CS_MONTH(...args);csHorses().forEach(h=>{HorseHealth.advance(csEnsure(h),csDay(),csContext(h),app);csSync(h);});return result;};
const CS_ELIGIBILITY=t2eligibility;
t2eligibility=function(h,e,setup={},session){if(h&&e){csEnsure(h);const error=HorseHealth.allowed(h,e.category==='Jumping'?'jump':e.id.startsWith('lunge-')?'lunge':e.category==='Groundwork'?'handling':'ridden',e.intensity);if(error)return error;if((session||t2state().session)?.saleTrial&&e.category==='Jumping'&&Number(setup.height??.5)>(session||t2state().session).saleTrial.maxHeight)return 'The seller limits the trial to the agreed safe schooling height.';}return CS_ELIGIBILITY(h,e,setup,session);};
const CS_ATTEMPT=t2attempt;
t2attempt=function(h,s){const result=CS_ATTEMPT(h,s);if(!result.blocked){const e=t2exercise(s.exerciseId),context=e.category==='Jumping'?'jump':e.id==='hoof'?'hooves':/circle|serpentine/.test(e.id)?'circle':e.category==='Groundwork'?'walk':'trot';for(const o of HorseHealth.observe(csEnsure(h),context,csDay(),`${s.id}:${s.attempts}`))s.log.push({kind:'Observation',text:o.text,elapsed:s.elapsed});}return result;};
const CS_FINISH=t2finish;
t2finish=function(h,s){const result=CS_FINISH(h,s);if(!s.carePostChecked){s.carePostChecked=true;const observations=HorseHealth.observe(csEnsure(h),'post',csDay(),s.id);result.notes.push(...observations.map(o=>o.text));if(s.saleTrial){const tx=HorseSales.state(app).transactions.find(t=>t.id===s.saleTrial.transactionId);if(tx){tx.trial=true;tx.status='Trial Completed';tx.trialNotes=result.exercises.map(e=>({name:e.name,result:e.result,text:e.text}));}}}return result;};
const CS_FIND_HORSE=t2findHorse;
t2findHorse=function(id){return CS_FIND_HORSE(id)||app.sales2?.listings.find(l=>l.horseId===id)?.horse;};
const CS_COMPETE=canCompeteUnderSaddle;
canCompeteUnderSaddle=function(h){csEnsure(h);return !HorseHealth.allowed(h,'competition',3)&&!HorseHealth.documentation(h,app.healthPolicy||'Local leisure',csDay()).length&&CS_COMPETE(h);};
function csNotice(result){if(result?.message)alert(result.message);render();saveGame(false);}
function csHealthMarkup(h){const view=HorseHealth.publicView(csEnsure(h));return `<details class="box"><summary>Horse Health Observation</summary><h4>Visible Concerns & My Observations</h4>${view.observations.slice(-12).map(o=>`<p>${csDate(o.day)}: ${csEscape(o.text)} — ${csEscape(o.strength)}</p>`).join('')||'<p>None noticed. This does not exclude a subtle problem.</p>'}<h4>Vet Findings</h4>${h.vetVisits.slice(-4).map(v=>`<p>${csEscape(v.tests.join(', '))}: ${csEscape(v.observed.join('; ')||'No clear cause identified in the tests performed.')} ${csEscape(v.uncertainty)}</p>`).join('')||'<p>No assessment recorded.</p>'}<h4>Confirmed Conditions</h4>${view.confirmed.map(d=>`<p>${csEscape(d.name)} ${d.resolved?'— resolved':'— documented'}</p>`).join('')||'<p>None currently confirmed.</p>'}<h4>Past Medical History</h4>${view.history.map(c=>`<p>${csEscape(c.name)}: ${csEscape(c.stage)}</p>`).join('')||'<p>No documented past condition.</p>'}<h4>Upcoming Care</h4>${view.upcoming.filter(p=>p.status==='Active').map(p=>`<p>Follow-up: ${csDate(p.followup)}</p>`).join('')}<p>Hoof review: ${csDate(h.hoofHealth.nextDue)}</p><button data-cs-health="${csEscape(h.id)}">Observe / Contact Veterinarian</button></details>`;}
const CS_CARD=createHorseCard;
createHorseCard=function(h){csEnsure(h);csSync(h);const node=CS_CARD(h);const health=document.createElement('div');health.innerHTML=csHealthMarkup(h);node.appendChild(health);health.querySelector('[data-cs-health]').onclick=()=>{app.vetSelection={...(app.vetSelection||{}),horseId:h.id};changeTab('vet');renderVet();};for(const action of ['list-sale','npc-sell']){const b=node.querySelector(`[data-action='${action}']`);if(b)b.onclick=()=>csOpenSaleForm(node,h);}return node;};
function csSelectHorse(panel,id,handler){const select=panel.querySelector(id);if(select)select.onchange=()=>{app.vetSelection={...(app.vetSelection||{}),horseId:select.value};handler();};}
function csHorseOptions(selected){return app.horses.map(h=>`<option value="${csEscape(h.id)}" ${h.id===selected?'selected':''}>${csEscape(h.name)}</option>`).join('');}
function csReceiptMarkup(){return `<details class="box"><summary>Care Receipts & Inventory</summary>${(app.careEconomy?.inventory||[]).map(i=>`<p>${csEscape(i.item)} × ${i.quantity} ${csEscape(i.horseId||'stable supplies')}</p>`).join('')}${(app.careEconomy?.receipts||[]).slice(-20).reverse().map(r=>`<p>${csEscape(r.number)} · ${csDate(r.date)} · ${csEscape(r.stable)} · ${csEscape(r.horse||'Stable')} · ${r.items.map(i=>`${csEscape(i.name)} × ${i.quantity} @ ${money(i.unitPrice)}`).join(', ')} · ${money(r.total)} · ${csEscape(r.status)} ${r.prescription?'· '+csEscape(r.prescription):''}</p>`).join('')}</details>`;}
const CS_VET=renderVet;
renderVet=function(){
  CS_VET();const panel=document.getElementById('vet'),basic=panel.querySelector('.grid.two > .box'),geld=panel.querySelector('#vet-gelding');
  const id=app.vetSelection?.horseId||app.horses[0]?.id,h=app.horses.find(h=>h.id===id);if(!basic)return;
  basic.innerHTML=`<h3>Veterinary Consultation</h3><label>Horse<select id="vet-horse">${csHorseOptions(id)}</select></label>${h?`<p>What have you noticed about ${csEscape(h.name)}?</p><label>Observation<select id="cs-observe">${csOptions(['stall','pasture','legs','hooves','walk','trot','circle','tack','post'])}</select></label><button id="cs-inspect">Observe & Record</button><label>Your concern<input id="cs-concern" maxlength="240" placeholder="Describe what you noticed"></label><button id="cs-record">Describe Symptoms</button><p class="small">Observations are clues. They do not establish a diagnosis.</p><label>Consultation topic<select id="cs-vet-topic">${csOptions(['Describe Symptoms','Discuss Existing Condition','Ask About Diagnostic Tests','Ask About Treatment','Ask About Medication','Ask About Vaccinations','Ask About Training Restrictions'])}</select></label><button id="cs-vet-discuss">Discuss</button><p id="cs-vet-reply" role="status"></p><label>Examination<select id="cs-exam">${Object.entries(HorseHealth.exams).filter(([key])=>!['hoof','joint'].includes(key)).map(([key,[name,price]])=>`<option value="${key}">${csEscape(name)} — ${money(price)}</option>`).join('')}</select></label><button id="cs-examine">Authorize Examination</button>${csHealthMarkup(h)}<h4>Treatment & Rehabilitation</h4>${HorseHealth.current(h).filter(c=>c.confirmed).map(c=>`<p>${csEscape(HorseHealth.definition(c).name)} — ${csEscape(c.stage)}</p><button data-cs-plan="${csEscape(c.id)}">Discuss & Record Care Plan</button>`).join('')||'<p>Assess the horse before selecting treatment.</p>'}${h.rehabilitationPlans.filter(p=>p.status==='Active').map(p=>`<p>${csEscape(p.care)}. Review on ${csDate(p.followup)}. ${p.supplies.length?'Required supplies: '+p.supplies.map(csEscape).join(', '):''}</p>`).join('')}${csCareTaskMarkup(h)}<h4>Vaccination Review</h4><label>Game region / exposure policy<select id="cs-policy">${csOptions(Object.keys(HorseHealth.vaccinePolicies),app.healthPolicy||'Local leisure')}</select></label><label>Veterinary vaccine plan<select id="cs-vaccine">${csOptions(HorseHealth.vaccinePolicies[app.healthPolicy||'Local leisure'].vaccines)}</select></label><button id="cs-vaccinate">Authorize Veterinary Appointment ($60)</button><p class="small">Vaccination does not guarantee illness is impossible. Initial game courses require a recorded follow-up.</p>${h.vaccinations.map(v=>`<p>${csEscape(v.vaccine)}: ${csEscape(v.courseStatus)} · next due ${csDate(v.nextDue)}</p>`).join('')}`:'<p>No horses selected.</p>'}`;
  if(geld)basic.appendChild(geld);csSelectHorse(panel,'#vet-horse',renderVet);if(!h)return;
  panel.querySelector('#cs-inspect').onclick=()=>{HorseHealth.observe(h,panel.querySelector('#cs-observe').value,csDay(),`inspection:${csDay()}:${panel.querySelector('#cs-observe').value}`);csNotice({});};
  panel.querySelector('#cs-record').onclick=()=>{const text=panel.querySelector('#cs-concern').value.trim();if(text)h.playerObservations.push({day:csDay(),context:'Player report',text,strength:'Unconfirmed player concern'});csNotice({});};
  panel.querySelector('#cs-vet-discuss').onclick=()=>{const topic=panel.querySelector('#cs-vet-topic').value;const replies={'Describe Symptoms':h.playerObservations.length?'I have reviewed your recorded observations. When is the change most noticeable? Choose a relevant examination.':'What have you noticed? You can observe the horse and record a concern first.','Discuss Existing Condition':h.confirmedDiagnoses.length?'We will consider the documented diagnoses and current findings together.':'There is no confirmed diagnosis in the available records.','Ask About Diagnostic Tests':'Targeted tests are useful when relevant to the findings. No test can reveal every possible condition.','Ask About Treatment':'The plan depends on a confirmed condition. Recovery may require care, time and reassessment.','Ask About Medication':'Medication requires a matching veterinary prescription. A package represents an authorized game course; it does not remove work restrictions.','Ask About Vaccinations':'We review history, travel and exposure using the selected regional game policy.','Ask About Training Restrictions':HorseHealth.allowed(h,'ridden',2)||'No current medical restriction on suitable light work has been established. Continue to monitor the horse.'};panel.querySelector('#cs-vet-reply').textContent=replies[topic];};
  panel.querySelector('#cs-examine').onclick=()=>csNotice(HorseHealth.examine(app,h,panel.querySelector('#cs-exam').value,csDay(),csId('exam')));
  panel.querySelectorAll('[data-cs-plan]').forEach(b=>b.onclick=()=>csNotice(HorseHealth.plan(h,b.dataset.csPlan,csDay())));
  panel.querySelector('#cs-policy').onchange=()=>{app.healthPolicy=panel.querySelector('#cs-policy').value;csNotice({});};
  panel.querySelector('#cs-vaccinate').onclick=()=>csNotice(HorseHealth.vaccinate(app,h,panel.querySelector('#cs-vaccine').value,app.healthPolicy||'Local leisure',csDay(),csId('vaccine')));
  csBindCare(panel,h);csPharmacy(panel,h);panel.insertAdjacentHTML('beforeend',csReceiptMarkup());
};
function csPharmacy(panel,h){const div=document.createElement('div');div.className='box';div.innerHTML=`<h3>Medical Supply Shop & Veterinary Pharmacy</h3><label>Supply<select id="cs-supply">${Object.values(HorseHealth.supplies).map(p=>`<option value="${csEscape(p.name)}">${csEscape(p.name)} — ${money(p.price)}</option>`).join('')}</select></label><label>Quantity<input id="cs-quantity" type="number" min="1" max="100" value="1"></label><button id="cs-buy-supply">Purchase Supplies</button><h4>Prescriptions for ${csEscape(h.name)}</h4>${h.prescriptions.map(rx=>`<p>${csEscape(rx.item)} · authorized packages ${rx.quantity} · dispensed ${rx.dispensed} · valid through day ${rx.expires} · competition restriction through day ${rx.competitionHoldUntil}</p><button data-cs-fill="${csEscape(rx.id)}">Fill Authorized Package (${money(HorseHealth.medicines[rx.item]?.price||0)})</button><button data-cs-admin="${csEscape(rx.id)}">${rx.professionalOnly?'Book Professional Course':'Record Prepared Authorized Course'}</button>`).join('')||'<p>No prescriptions. Medicine cannot be substituted with ordinary supplies.</p>'}`;panel.appendChild(div);div.querySelector('#cs-buy-supply').onclick=()=>csNotice(HorseHealth.purchase(app,h,div.querySelector('#cs-supply').value,Number(div.querySelector('#cs-quantity').value),csDay(),csId('supply')));div.querySelectorAll('[data-cs-fill]').forEach(b=>b.onclick=()=>{const rx=h.prescriptions.find(r=>r.id===b.dataset.csFill);csNotice(HorseHealth.purchase(app,h,rx.item,1,csDay(),csId('rx'),rx.id));});div.querySelectorAll('[data-cs-admin]').forEach(b=>b.onclick=()=>csNotice(HorseHealth.administer(app,h,b.dataset.csAdmin,csDay(),csId('course'))));}
function csCareTaskMarkup(h){return `<details><summary>Permitted Care & Handling</summary><p>Review the veterinary plan, gather its supplies, and approach calmly. Stop when the horse cannot safely tolerate care.</p><label>Handling choice<select id="cs-care-choice">${csOptions(['Calm introduction','Pause and reassess','Stop and seek professional help'])}</select></label><button id="cs-care">Prepare & Perform Permitted Care</button></details>`;}
function csBindCare(panel,h){const b=panel.querySelector('#cs-care');if(!b)return;b.onclick=()=>{if(panel.querySelector('#cs-care-choice').value!=='Calm introduction')return csNotice({message:'The care task was paused safely. No supplies were consumed.'});const plans=h.rehabilitationPlans.filter(p=>p.status==='Active');if(!plans.length)return csNotice({message:'A current veterinary care plan is required.'});const results=plans.map(p=>{const c=HorseHealth.current(h).find(c=>c.id===p.conditionId);return c?HorseHealth.careDay(app,h,c,csDay(),csContext(h)):null;}).filter(Boolean);csNotice({message:results.every(r=>r.ok)?'Authorized care is recorded for today. Scheduled daily care continues when time advances.':results.filter(r=>!r.ok).map(r=>r.reason).join('; ')});};}
renderFarrier=function(){const panel=document.getElementById('farrier'),id=app.vetSelection?.horseId||app.horses[0]?.id,h=app.horses.find(h=>h.id===id);if(h)csEnsure(h);panel.innerHTML=`<h2>Farrier</h2><div class="box"><label>Horse<select id="cs-farrier-horse">${csHorseOptions(id)}</select></label>${h?`<p>When was this horse last trimmed or shod?</p><p>${h.hoofHealth.history.length?'Last service on '+csDate(h.hoofHealth.history.at(-1).day):'The hoof-care history is incomplete. We will assess the actual condition.'}</p><label>Discuss / book service<select id="cs-farrier-service">${Object.entries(HorseHealth.farrierServices).map(([id,[name,price]])=>`<option value="${id}">${csEscape(name)} — ${money(price)}</option>`).join('')}</select></label><label>Handling choice<select id="cs-farrier-handling"><option value="pause">Assess and pause if unsettled</option><option value="prepare">Calm preparation; stop if still unsafe</option></select></label><button id="cs-farrier-complete">Authorize Assessment & Service</button><p>Barefoot and shoeing choices depend on this horse's needs. Neither grants discipline skills.</p><p>Next hoof review: ${csDate(h.hoofHealth.nextDue)}</p>${h.hoofHealth.history.map(v=>`<p>${csDate(v.day)}: ${csEscape(HorseHealth.farrierServices[v.service][0])}. ${v.findings.map(csEscape).join(' ')} Receipt ${csEscape(v.receipt)}</p>`).join('')}`:'<p>No horse selected.</p>'}</div>${csReceiptMarkup()}`;csSelectHorse(panel,'#cs-farrier-horse',renderFarrier);if(h)panel.querySelector('#cs-farrier-complete').onclick=()=>{const r=HorseHealth.farrier(app,h,panel.querySelector('#cs-farrier-service').value,csDay(),csId('farrier'),panel.querySelector('#cs-farrier-handling').value);csSync(h);csNotice(r);};};
function csProspects(){
  csImportListings();HorseSales.advanceMarket(app,csDay());const s=HorseSales.state(app);if(s.prospectsSeeded)return;s.prospectsSeeded=true;
  for(const [kind,price]of [['untrained',2000],['trained',10000],['fully',75000]]){const h=baseHorse(kind,'npc');h.owner='Prospects Pasture';HorseSales.list(app,h,price,csDay());}
}
function csSaleMarkup(l){const h=l.horse;return `<article class="box"><h3>${csEscape(h.name)}</h3><p>${csEscape(h.breed)} · ${h.age} · ${csEscape(h.gender)} · ${csEscape(h.height)} · ${csEscape(h.coat||'')}</p><p>Asking ${money(l.ask)} · ${csEscape(l.seller)} · ${csEscape(l.location)}</p><p>Main discipline: ${csEscape(({jumping:'Showjumping',dressage:'Dressage',hunter:'Hunters',eventing:'Eventing'})[l.mainDiscipline]||l.mainDiscipline)} · Advertised level: ${csEscape(l.claimedLevel)}. Trial ${l.trialAvailable?'available':'unavailable'}. Records ${l.recordsAvailable?'available':'incomplete'}.</p><p>${csEscape(h.personality||'Temperament not disclosed')} · ${(h.showResults||[]).length} recorded competition results</p><button data-cs-inquire="${csEscape(l.id)}">${l.direction==='sell'?'Manage Sale / Contact Buyer':'Contact Seller'}</button></article>`;}
