function csTrial(tx,choice){
  if(!HorseSales.active(app,tx)||tx.direction!=='buy')return {ok:false,message:'An active buying inquiry is required.'};
  if(t2state().session)return {ok:false,message:'Finish the current training or trial session first.'};
  const l=HorseSales.listing(app,tx),h=l.horse;if(!l.trialAvailable)return {ok:false,message:'A ridden trial is not available for this horse.'};
  const draft={horseId:h.id,discipline:choice==='jump'?'jumping':'flatwork',facilityId:t2facilities().find(f=>f.location==='Indoor')?.id||'outdoor',length:25,goal:'Balance',lesson:choice==='jump'?['crossrail','vertical']:['large-circle','walk-trot','downward']};
  const r=t2start(h,draft);if(!r.ok)return r;r.session.saleTrial={transactionId:tx.id,maxHeight:Math.min(.8,t2permittedHeight(h))};tx.status='Trial Requested';t2state().draft={...draft};return r;
}
