mgCatalog('Smooth Spurs','spurs',[['Rounded Dummy Spurs',35],['Rounded Short-Neck Spurs',42],['Smooth Roller Spurs',65]]);
EQ_SLOTS.crop='Riding Crops';EQ_SLOTS.spurs='Smooth Spurs';
function csAidEligible(h,s,kind){const item=mgOwned(h.equipmentRefs?.[kind]);if(!item||item.condition<=0||item.assignedHorseId!==h.id||mgType(item.type)?.slot!==kind)return false;const t=t2horse(h),e=t2exercise(s.exerciseId);if(!e||e.category==='Groundwork'||s.tension>=30||HorseHealth.current(csEnsure(h)).length||Math.min(t.education.leg,t.education.rein)<50)return false;if(kind==='spurs'&&(app.riderExperience??0)<50)return false;if(item.type==='Smooth Roller Spurs'&&(app.riderExperience??0)<80)return false;if(item.type==='Jumping Bat'&&e.category!=='Jumping')return false;if(item.type==='Dressage Whip'&&e.category==='Jumping')return false;return !t2sensitivity(h,s.intensity).strong;}
function csAidAdjustment(h,e,s,c){
  if(s.riderAid!=='Spurs')return 0;
  if(!csAidEligible(h,s,'spurs'))return 0;
  return ['leg-yield','shoulder-in','hindquarters','shoulders'].includes(e.id)?-1.5:0;
}
const CS_PROBABILITY=t2probability;
t2probability=function(h,event,base,c={},primary,secondary,s){const p=CS_PROBABILITY(h,event,base,c,primary,secondary,s);if(event==='forward'&&s?.riderAid==='Crop'&&csAidEligible(h,s,'crop'))p.chance=Math.max(0,p.chance-2);return p;};
const CS_AID_ATTEMPT=t2attempt;
t2attempt=function(h,s){
  const aid=s.riderAid,kind=aid==='Crop'?'crop':aid==='Spurs'?'spurs':null;
  if(kind&&!csAidEligible(h,s,kind))return {blocked:true,message:'The selected equipment is unsuitable for this horse, rider or cue. Choose ordinary aids or suitable owned equipment.'};
  const previous=s.attempts,result=CS_AID_ATTEMPT(h,s);if(s.attempts>previous&&kind){const e=t2exercise(s.exerciseId),unneeded=kind==='spurs'&&!['leg-yield','shoulder-in','hindquarters','shoulders'].includes(e.id)||kind==='crop'&&!(s.log.some(x=>x.event==='forward'));
    if(unneeded){s.unnecessaryAdditionalAids=(s.unnecessaryAdditionalAids||0)+1;if(s.unnecessaryAdditionalAids>1){s.tension=clamp(s.tension+3,0,100);s.careQualityPenalty=Math.min(.2,(s.careQualityPenalty||0)+.05);s.log.push({kind:'Aid',text:'The additional aid is unnecessary for this response. The horse becomes tense after repeated unnecessary cues.',elapsed:s.elapsed});}}
  }
  if(s.attempts>previous)csFearExposure(h,t2exercise(s.exerciseId).id,s.id+':'+s.attempts,s);
  return result;
};
const CS_ORIGINAL_AWARD=originalSkillAward;
originalSkillAward=function(h,e,s,result,repeat,c,m){return CS_ORIGINAL_AWARD(h,e,s,result,repeat,c,{...m,learning:m.learning*(1-(s.careQualityPenalty||0))});};
const CS_EDITOR=t2editorMarkup;
t2editorMarkup=function(){const html=CS_EDITOR(),s=t2state().session;if(!s)return html;const h=t2findHorse(s.horseId);if(!h)return html;const selectors=['crop','spurs'].map(kind=>`<label>${kind==='crop'?'Crop':'Spurs'}<select data-cs-aid="${kind}"><option value="">None</option>${mgState().items.filter(i=>mgType(i.type)?.slot===kind&&(!i.assignedHorseId||i.assignedHorseId===h.id)).map(i=>`<option value="${csEscape(i.id)}" ${h.equipmentRefs?.[kind]===i.id?'selected':''}>${csEscape(i.type)}</option>`).join('')}</select></label>`).join('');return html.replace('<label>Optional Rider Aid',selectors+'<label>Optional Rider Aid').replace('Very Light','Extra Light').replace('>Normal<','>Moderate<');};
const CS_BIND=t2bind;
