const CS_EXPERIENCE_FINISH=t2finish;
t2finish=function(h,s){const first=!s.finished,result=CS_EXPERIENCE_FINISH(h,s);if(first&&s.attempts&&!s.saleTrial&&s.riddenMinutes>0)app.riderExperience=Math.min(100,(app.riderExperience||0)+1);return result;};
// Rescue needs and fears are generated once; discovery records real relevant encounters.
const CS_RESCUE_PROFILES=[['Poor nutrition',18],['Low handling education',18],['Specific fear',14],['Previous medical history',12],['Multiple moderate needs',18],['Mostly healthy retraining',15],['Complex rehabilitation',5]];
const CS_FEAR_CONTEXT={hoof:'Hoof-Handling Difficulties',farrier:'Nervous with Farrier',clip:'Sensitive to Clipping',equipment:'Equipment Cautious',mount:'Difficult to Mount',water:'Water-Shy',filler:'Hesitates at Fillers',traffic:'Traffic Nervous',gate:'Nervous Around Arena Gates'};
function csRescueProfile(h){if(h.rehabilitationProfile)return h.rehabilitationProfile;const seed=HorseHealth.hash(h.id+'|rescue'),value=HorseHealth.roll(seed,'profile')*100;let cursor=0;const profile=CS_RESCUE_PROFILES.find(r=>(cursor+=r[1])>value)[0],f=HorseHealth.roll(seed,'fear-count'),count=f<.30?0:f<.72?1:f<.94?2:3,keys=Object.keys(CS_FEAR_CONTEXT).sort((a,b)=>HorseHealth.roll(seed,a)-HorseHealth.roll(seed,b));h.rehabilitationProfile={profile,stage:profile==='Mostly healthy retraining'?'Education':'Intake',hiddenFears:keys.slice(0,count).map(context=>({context,trait:CS_FEAR_CONTEXT[context],exposures:0,known:false,history:[]})),handlingDays:[]};return h.rehabilitationProfile;}
function csFearExposure(h,exercise,eventId,session){if(!h.isRescue)return;const p=csRescueProfile(h);for(const fear of p.hiddenFears){if(fear.context!==exercise||fear.history.some(r=>r.eventId===eventId))continue;fear.exposures++;const found=HorseHealth.roll(h.healthSeed,`fear:${fear.context}:${fear.exposures}`)<[.65,.80,.95][Math.min(2,fear.exposures-1)];fear.history.push({day:csDay(),eventId,found});if(found){fear.known=true;const traits=t2horse(h).traits;if(!traits.includes(fear.trait))traits.push(fear.trait);}if(session){session.tension=clamp(session.tension+5,0,100);session.log.push({kind:'Handling observation',text:found?`New Handling Concern Discovered: ${fear.trait}`:'The horse becomes tense during this specific encounter. The cause is not yet clear.',elapsed:session.elapsed});}}}
const CS_GENERATE_RESCUE=generateRescueHorse;
generateRescueHorse=function(){const template=CS_GENERATE_RESCUE(),profile=csRescueProfile(template);template.legacyAdvertisedIssues=template.issues;template.issues=[];template.unridable=false;template.isGreen=profile.profile==='Low handling education'||profile.profile==='Mostly healthy retraining';template.weightStatus=['Poor nutrition','Multiple moderate needs','Complex rehabilitation'].includes(profile.profile)?'Underweight':'Moderate';template.rescueWeightDelay=0;template.note='Individual intake and rehabilitation needs. Request a veterinary assessment; undiscovered concerns are not listed.';return template;};
const CS_WEIGHT=updateWeight;
updateWeight=function(h,delta){if(h.isRescue&&h.medicalVersion){const rescue=h.isRescue;h.isRescue=false;try{return CS_WEIGHT(h,delta);}finally{h.isRescue=rescue;}}return CS_WEIGHT(h,delta);};
renderRescue=function(){const panel=document.getElementById('rescue');panel.innerHTML=`<h2>Rescue Intake & Rehabilitation</h2><div class="cards">${(app.rescueHorses||[]).map(t=>`<article class="box"><h3>${csEscape(t.name)}</h3><p>${csEscape(t.breed)} · ${t.ageLabel||t.age} · ${csEscape(t.gender)} · visible condition: ${csEscape(t.weightStatus)}</p><p>${csEscape(t.note)}</p><p>Adoption fee ${money(t.rescueFee||0)}</p><button data-cs-adopt="${csEscape(t.id)}">Review Intake & Adopt</button></article>`).join('')}</div><h3>Current Rehabilitation</h3>${app.horses.filter(h=>h.isRescue).map(h=>`<div class="box"><h4>${csEscape(h.name)}</h4><p>Current phase: ${csEscape(csRescueProfile(h).stage)}</p>${csHealthMarkup(h)}<p>Known handling concerns: ${csRescueProfile(h).hiddenFears.filter(f=>f.known).map(f=>csEscape(f.trait)).join(', ')||'None discovered.'}</p><button data-cs-rehab="${csEscape(h.id)}">Review Welfare & Next Phase</button></div>`).join('')}`;panel.querySelectorAll('[data-cs-adopt]').forEach(b=>b.onclick=()=>{const t=app.rescueHorses.find(t=>t.id===b.dataset.csAdopt);if(!t||!tryCharge(t.rescueFee||0))return;let h=t.actualHorse;if(!h){h=baseHorse('untrained','npc');Object.assign(h,{name:t.name,breed:t.breed||h.breed,age:t.age,gender:t.gender,weightStatus:t.weightStatus,owner:'Your Stable',isRescue:true,rescueId:t.id,requiresBreakingIn:t.isGreen,rescueWeightDelay:0,rehabilitationProfile:t.rehabilitationProfile});for(const issue of t.issues||[])HorseHealth.add(h,'legacy',csDay(),{legacyName:issue.name,known:true,confirmed:true});const profile=csRescueProfile(h);if(['Previous medical history','Multiple moderate needs','Complex rehabilitation'].includes(profile.profile)){const c=HorseHealth.add(h,profile.profile==='Complex rehabilitation'?'tendon':'imbalance',csDay(),{cause:'Pre-existing rescue intake condition'});if(profile.profile==='Previous medical history'){c.resolved=true;c.stage='Resolved';c.known=true;c.confirmed=true;h.confirmedDiagnoses.push({conditionId:c.id,name:HorseHealth.definition(c).name,day:csDay()});h.previousConditions.push(HorseHealth.copy(c));}}t.actualHorse=h;}h.owner='Your Stable';app.horses.push(h);app.rescueHorses=app.rescueHorses.filter(x=>x.id!==t.id);csNotice({message:'Intake recorded. Assess the horse’s actual needs before demanding work.'});});panel.querySelectorAll('[data-cs-rehab]').forEach(b=>b.onclick=()=>{const h=app.horses.find(h=>h.id===b.dataset.csRehab),p=csRescueProfile(h);p.stage=HorseHealth.current(csEnsure(h)).length||['Underweight','Very Underweight'].includes(h.weightStatus)?'Stabilization':(h.behavior||0)<500?'Handling':h.requiresBreakingIn?'Education':'Sport / ordinary development';csNotice({message:'The next phase reflects current welfare and education, without a mandatory calendar lock.'});});panel.querySelectorAll('[data-cs-health]').forEach(b=>b.onclick=()=>{app.vetSelection={horseId:b.dataset.csHealth};changeTab('vet');renderVet();});};

const CS_CLEANUP=mgCleanupAssignments;
mgCleanupAssignments=function(){const saved=mgState().items.filter(i=>i.assignedHorseId===t2state().session?.horseId&&t2state().session?.saleTrial).map(i=>({item:i,horse:i.assignedHorseId,slot:i.assignedSlot}));CS_CLEANUP();for(const r of saved){r.item.assignedHorseId=r.horse;r.item.assignedSlot=r.slot;}};
const CS_SIZE_EFFECTS=mgSizeEffects;
mgSizeEffects=function(item,h){if(['crop','spurs'].includes(mgType(item?.type)?.slot))return {ok:true,comfort:0,control:0,learn:0,fail:0};return CS_SIZE_EFFECTS(item,h);};
function csListingSchooling(listing){
  if(listing.schoolingVersion===1)return listing;
  const h=listing.horse,disciplines=Object.keys(SHOW_LEVELS),scores=disciplines.map(d=>({discipline:d,score:horseDisciplineAverage(h,d)})).sort((a,b)=>b.score-a.score);
  const preferred=t2canonicalDiscipline(h.mainDiscipline||h.discipline||''),best=scores[0],chosen=scores.find(s=>s.discipline===preferred&&s.score>=best.score-5)||best;
  listing.mainDiscipline=chosen.discipline;listing.trialAvailable=h.age>=3&&!h.requiresBreakingIn&&canRideUnderSaddle(h);listing.marketAbility=Math.max(0,Math.min(1,chosen.score/100));
  const actual=highestAllowedLevelIndex(h,chosen.discipline),minimum=requiredSkillBand(chosen.discipline,SHOW_LEVELS[chosen.discipline][0])[0];
  const green=h.age<3||h.requiresBreakingIn||!canRideUnderSaddle(h),foundation=chosen.score<minimum;
  const seed=HorseHealth.hash(h.id+'|advertised-schooling'),r=HorseHealth.roll(seed,'claim');
  // Small, fixed seller differences. No claimed advanced level for an unstarted horse.
  let adjustment=0;if(!green&&!foundation){if(listing.sellerType==='Overoptimistic advertiser'||listing.sellerType==='Deliberately misleading seller')adjustment=r<.75?1:0;else if(listing.sellerType==='Private straightforward owner')adjustment=r<.08?-1:0;}
  const advertised=Math.max(0,Math.min(SHOW_LEVELS[chosen.discipline].length-1,actual+adjustment));
  listing.actualLevelIndex=actual;listing.claimedLevelIndex=advertised;listing.claimAdjustment=advertised-actual;
  listing.claimedLevel=green?'Unstarted — groundwork education':foundation?'Early foundations — below introductory competition level':chosen.discipline==='jumping'?`${Math.round(Number(SHOW_LEVELS.jumping[advertised])*100)} cm`:SHOW_LEVELS[chosen.discipline][advertised];
  listing.schoolingVersion=1;return listing;
}
const CS_IMPORT_LISTINGS=csImportListings;
csImportListings=function(){CS_IMPORT_LISTINGS();HorseSales.state(app).listings.forEach(csListingSchooling);};
const CS_SALES_LIST=HorseSales.list;
HorseSales.list=function(...args){return csListingSchooling(CS_SALES_LIST(...args));};
function csSellerTack(l){
  if(l.sellerTackVersion===1||l.direction==='sell')return l;
  // Player-owned horses are never re-equipped by listing migration.
  if(app.horses.some(h=>h.id===l.horseId)){l.sellerTackVersion=1;return l;}
  const h=l.horse,seed=HorseHealth.hash(h.id+'|seller-tack'),pick=(key,types)=>types[Math.floor(HorseHealth.roll(seed,key)*types.length)];
  const discipline=l.mainDiscipline,setup={bridle:pick('bridle',['Snaffle Bridle','Anatomical Bridle','Flash Bridle','Plain Cavesson Bridle','Figure-8 Bridle']),bit:pick('bit',['Loose Ring Snaffle','Eggbutt Snaffle','D-Ring Bit','French Link Snaffle','Full Cheek Snaffle']),saddle:pick('saddle',discipline==='dressage'?['Dressage Saddle','Dressage Saddle','All-Purpose Saddle','Close-Contact Saddle']:['Jumping Saddle','Close-Contact Saddle','All-Purpose Saddle','Dressage Saddle']),pad:pick('pad',['Anatomical Pad','Basic Cotton Pad','Sheepskin Half Pad','Thin Competition Pad','Memory Foam Pad','Shock-Absorbing Pad']),forelegs:pick('legs',['Tendon Boots','Brushing Boots','Polo Wraps','Cross-Country Boots'])};
  if(HorseHealth.roll(seed,'strong-bit')<.15)setup.bit='Pelham Bit';
  if(HorseHealth.roll(seed,'breastplate')<.45)setup.breastplate=pick('breastplate-type',['Five-Point Breastplate','Standard Breastplate','Hunting Breastplate']);
  mgSizing(h);const body=horseBody(h),fit=HorseHealth.roll(seed,'fit'),delta=fit<.12?65:fit<.32?42:fit<.65?20:5;
  const colors=['Black','Dark Brown','Brown','Navy','Burgundy'];
  l.sellerTackItems=Object.entries(setup).map(([slot,type])=>{const t=mgType(type),condition=55+Math.floor(HorseHealth.roll(seed,slot+':condition')*46),item={id:`seller-tack:${l.id}:${slot}`,type:t.id,slot,assignedSlot:slot,assignedHorseId:h.id,originalPrice:t.price,condition,uses:0,size:slot==='bit'?h.preferredBitSize:slot==='saddle'?17.5:h.tackSize,color:pick(slot+':color',colors),sellerOwned:true};if(slot==='saddle')item.saddleDimensions=Object.fromEntries(Object.entries(body).map(([k,v])=>[k,clamp(v+(v<50?delta:-delta),0,100)]));if(slot==='breastplate')item.basicFit=HorseHealth.roll(seed,'breastplate-fit')<.2?'Incorrect':'Correct';if(slot==='bit'&&HorseHealth.roll(seed,'bit-fit')<.15)item.size+=.25;return item;});
  l.previousTackSnapshot=HorseHealth.copy(h.tack||{});h.sellerTackId=l.id;h.tack={...setup};l.sellerTackVersion=1;
  const offered=HorseHealth.roll(seed,'offer')<.65;
  l.tackOffers=offered?l.sellerTackItems.filter(i=>HorseHealth.roll(seed,i.slot+':sell')<.72).map(i=>({...HorseHealth.copy(i),salePrice:Math.round(i.originalPrice*(.45+i.condition/400))})):[];
  return l;
}
const CS_SCHOOLING=csListingSchooling;
csListingSchooling=function(l){CS_SCHOOLING(l);return csSellerTack(l);};
function csActiveSeller(h){return !app.horses.some(o=>o.id===h.id)&&HorseSales.state(app).listings.find(l=>l.id===h.sellerTackId&&l.status!=='Complete');}
const CS_EQ_ITEMS=eqItems;
eqItems=function(h,override=null){const l=csActiveSeller(h);if(l?.sellerTackItems&&!override)return l.sellerTackItems.map(item=>({slot:item.slot,type:item.type,item}));return CS_EQ_ITEMS(h,override);};
const CS_SADDLE_FIT=saddleFit;
saddleFit=function(h,override=null){if(!csActiveSeller(h)||override||app.settings.saddleFitting)return CS_SADDLE_FIT(h,override);const previous=app.settings.saddleFitting;app.settings.saddleFitting=true;try{return CS_SADDLE_FIT(h,override);}finally{app.settings.saddleFitting=previous;}};
function csTackOptions(tx){const l=HorseSales.listing(app,tx);return (l.tackOffers||[]).length?`<details open><summary>Optional Seller Tack — Select Items to Buy With Horse</summary><p>Seller equipment is used during the trial. Fit and comfort depend on the horse and the actual items; a saddle fitting review may be useful.</p>${l.tackOffers.map(i=>`<label><input type="checkbox" data-cs-tack-buy="${csEscape(i.id)}">${csEscape(i.type)} · ${csEscape(i.color)} · condition ${i.condition}/100 · ${money(i.salePrice)}</label>`).join('')}</details>`:'<p>The seller is not offering tack with this horse. Trial equipment remains the seller’s property.</p>';}
const CS_TRANSACTION_MARKUP=csTransactionMarkup;
csTransactionMarkup=function(tx){let html=CS_TRANSACTION_MARKUP(tx);if(!tx.contract&&tx.direction==='buy')html=html.replace('<label>Transport',csTackOptions(tx)+'<label>Transport');return html;};
const CS_SALES_PANEL=csSalesPanel;
csSalesPanel=function(panelId,studs=false){CS_SALES_PANEL(panelId,studs);const panel=document.getElementById(panelId),tx=HorseSales.state(app).transactions.find(t=>t.id===app.careSelectedTransaction),button=panel.querySelector('#cs-sale-contract');if(button&&tx)button.onclick=()=>{const l=HorseSales.listing(app,tx),chosen=Array.from(panel.querySelectorAll('[data-cs-tack-buy]:checked')).map(b=>l.tackOffers.find(i=>i.id===b.dataset.csTackBuy)).filter(Boolean);const r=HorseSales.contract(app,tx,csDay(),panel.querySelector('#cs-sale-transport').value);if(r.ok){tx.contract.equipment=HorseHealth.copy(chosen);tx.contract.equipmentCost=chosen.reduce((n,i)=>n+i.salePrice,0);}csNotice(r);};};
const CS_SALE_SAY=HorseSales.say;
HorseSales.say=function(app,tx,topic,day){if(topic!=='tack')return CS_SALE_SAY(app,tx,topic,day);if(!HorseSales.active(app,tx))return {ok:false,message:'This inquiry is closed.'};const l=HorseSales.listing(app,tx);csSellerTack(l);const text=`The current setup is ${(l.sellerTackItems||[]).map(i=>i.type+' ('+i.color+', '+i.condition+'/100 condition)').join(', ')||Object.values(l.horse.tack||{}).filter(Boolean).join(', ')}. ${(l.tackOffers||[]).length?'Selected items are available separately; choose them before preparing the contract.':'This equipment is not included in the sale.'} A trial and fitting assessment can help assess comfort.`;tx.conversation.push({day,topic,text});if(tx.status==='Inquiry Open')tx.status='Seller Contacted';return {ok:true,message:text};};

function csPreexisting(h){
  if(!h.careNewNPC||h.preexistingHealthProcessed||app.horses.some(o=>o.id===h.id))return;
  HorseHealth.seedSaleHealth(h,csDay());
}
const CS_PREEXISTING_LIST=HorseSales.list;
HorseSales.list=function(app,h,...args){csPreexisting(h);return CS_PREEXISTING_LIST(app,h,...args);};

const CS_COLLAPSIBLE_AD=csSaleMarkup;
csSaleMarkup=function(l){const h=l.horse,summary=`${csEscape(h.breed)} · ${h.age} years · ${csEscape(h.gender)}`;return CS_COLLAPSIBLE_AD(l).replace('<article class="box">',`<article class="box"><details class="sales-ad" data-ui-key="sale-ad-${csEscape(l.id)}"><summary>${summary}</summary><div class="sales-ad-body">`).replace('</article>','</div></details></article>');};

for(const t of MG_CATALOG.filter(t=>['crop','spurs'].includes(t.slot)))eqRule(t.id,'','');
// Follow-through on source-specific plans; correction changes care, never genetic potential.
const CS_SOURCE_VET=renderVet;
renderVet=function(){CS_SOURCE_VET();const panel=document.getElementById('vet'),h=app.horses.find(h=>h.id===(app.vetSelection?.horseId||app.horses[0]?.id));if(!h)return;const known=HorseHealth.current(csEnsure(h)).filter(c=>c.confirmed);if(!known.some(c=>HorseHealth.definition(c).correction))return;const node=document.createElement('div');node.className='box';node.innerHTML=`<h3>Review Contributing Factors</h3>${known.some(c=>HorseHealth.definition(c).correction==='tackCorrected')?'<p>Use the existing tack editor and fitting service to correct the source before recording reassessment.</p><button id="cs-tack-review">Record Current Tack Reassessment</button>':''}${known.some(c=>HorseHealth.definition(c).correction==='airQualityCorrected')?'<p>The plan calls for improved air quality and reduced dust exposure.</p><button id="cs-air-review">Record Environmental Management Change</button>':''}`;panel.appendChild(node);const tack=node.querySelector('#cs-tack-review');if(tack)tack.onclick=()=>{const fit=saddleFit(h);if(['Poor','Very Poor'].includes(fit.grade))return csNotice({message:'The current saddle still needs correction. Review the fitting assessment.'});h.tackConcernCorrected=true;csNotice({message:'Tack reassessment recorded. Recovery and follow-up still apply.'});};const air=node.querySelector('#cs-air-review');if(air)air.onclick=()=>{h.dustExposure=false;h.airQualityCorrected=true;csNotice({message:'Environmental management recorded. Continue the veterinary plan and reassessment.'});};};
const CS_MEDICATION_COMPETE=canCompeteUnderSaddle;
canCompeteUnderSaddle=function(h){if((h.prescriptions||[]).some(rx=>rx.used>0&&rx.competitionHoldUntil>=csDay()))return false;return CS_MEDICATION_COMPETE(h);};
const CS_CARE_CALENDAR=renderCalendar;
renderCalendar=function(){CS_CARE_CALENDAR();const panel=document.getElementById('calendar');if(!panel)return;panel.insertAdjacentHTML('beforeend',`<details class="box" data-ui-key="care-calendar"><summary>Health & Hoof Care Calendar</summary>${app.horses.filter(h=>!h.deceased).map(h=>{const view=HorseHealth.publicView(csEnsure(h));return `<h4>${csEscape(h.name)}</h4><p>Hoof review: ${csDate(h.hoofHealth.nextDue)}</p>${view.upcoming.filter(p=>p.status==='Active').map(p=>`<p>Veterinary follow-up: ${csDate(p.followup)}</p>`).join('')}${h.vaccinations.slice(-8).map(v=>`<p>${csEscape(v.vaccine)} · next appointment ${csDate(v.nextDue)}</p>`).join('')}`;}).join('')}</details>`);};

const CS_COMPLETED_WARMUP=t2eligibility;
t2eligibility=function(h,e,setup={},session){const result=CS_COMPLETED_WARMUP(h,e,setup,session);if(session?.warmup>0&&(/Include suitable trot and canter preparation|Complete a suitable warm-up/.test(result)))return '';return result;};
function csVisibleInjury(h){return HorseHealth.current(csEnsure(h)).some(c=>HorseHealth.definition(c).visible&&['skin','mouth'].includes(HorseHealth.definition(c).category));}
const CS_VISIBLE_OPTIONS=t2horseOptions;
t2horseOptions=function(horses,draft){let html=CS_VISIBLE_OPTIONS(horses,draft);for(const h of horses)if(csVisibleInjury(h)){const label=mgEscape(h.name||'Unnamed Horse');html=html.replace('>'+label,'>'+label+' • Visible injury');}return html;};
const CS_VISIBLE_EDITOR=t2editorMarkup;
t2editorMarkup=function(){let html=CS_VISIBLE_EDITOR();const session=t2state().session,h=session&&t2findHorse(session.horseId);if(h&&session.phase==='warmup'&&csVisibleInjury(h))html=html.replace('— '+mgEscape(h.name)+'</h3>','— '+mgEscape(h.name)+' <span class="visible-injury-marker">Visible injury</span></h3>');return html;};

// Rescue placement deadlines persist independently of monthly refreshes.
function csRescueDeadline(t,day=csDay()){
  if(!Number.isFinite(t.rescueListedDay))t.rescueListedDay=day;
  if(!Number.isFinite(t.rescueRemovalDay))t.rescueRemovalDay=t.rescueListedDay+30+Math.floor(HorseHealth.roll(t.id,'rescue-placement-window')*121);
  return t.rescueRemovalDay;
}
const CS_TIMED_RESCUE_GENERATOR=generateRescueHorse;
generateRescueHorse=function(){const t=CS_TIMED_RESCUE_GENERATOR();csRescueDeadline(t);return t;};
refreshRescueHorses=function(){
  const day=csDay();app.rescueHorses=app.rescueHorses||[];app.rescueListingHistory=app.rescueListingHistory||[];
  app.rescueHorses=app.rescueHorses.filter(t=>{if(csRescueDeadline(t,day)>day)return true;app.rescueListingHistory.push({...t,removedDay:t.rescueRemovalDay,placementStatus:'Placement listing closed'});return false;});
  while(app.rescueHorses.length<15)app.rescueHorses.push(generateRescueHorse());
};
const CS_RESCUE_DATE_HYDRATE=hydrateFromSave;
hydrateFromSave=function(data){const result=CS_RESCUE_DATE_HYDRATE(data);app.rescueListingHistory=data.rescueListingHistory||[];refreshRescueHorses();return result;};
const CS_TIMED_RESCUE_RENDER=renderRescue;
renderRescue=function(){refreshRescueHorses();CS_TIMED_RESCUE_RENDER();const panel=document.getElementById('rescue');const shop=document.createElement('section');shop.className='tack-shop rescue-shop';const hero=document.createElement('div');hero.className='tack-shop-hero';hero.innerHTML='<p class="shop-eyebrow">Care • Placement • A fresh start</p><h2>Rescue Intake & Rehabilitation</h2><p>Review individual needs and placement dates before adopting.</p>';const body=document.createElement('div');body.className='sales-shop-body';panel.querySelector('h2')?.remove();while(panel.firstChild)body.appendChild(panel.firstChild);shop.append(hero,body);panel.appendChild(shop);for(const b of panel.querySelectorAll('[data-cs-adopt]')){const t=app.rescueHorses.find(t=>t.id===b.dataset.csAdopt);const date=document.createElement('p');date.className='small';date.textContent='Placement listing closes '+csDate(csRescueDeadline(t));b.before(date);}};

const CS_CARE_RESET=resetGame;
resetGame=function(){csLastHealthDay=null;app.sales2={version:1,sequence:0,listings:[],transactions:[],history:[]};app.careEconomy={receipts:[],inventory:[],operations:{}};app.careSequence=0;app.riderExperience=0;app.careSelectedTransaction=null;app.rescueListingHistory=[];return CS_CARE_RESET();};
